mapper.select:
SELECT 
FROM pwork p JOIN work_exif e ON e.pid=p.pid
LEFT JOIN user u ON u.uid=p.uid LEFT JOIN pclist c ON c.pcid=p.pcid
WHERE p.wstatus='展示' AND p.pcid=#{pcid} AND p.pid != #{pid}
  AND e.focal > 0 AND e.aperture > 0
  AND ABS(LOG2(CASE WHEN e.aperture > 0 THEN e.aperture END)-LOG2(#{aperture})) <= #{apertureStopsMax}
  AND ABS(e.focal-#{focal})/#{focal} <= #{focalRelativeMax}
ORDER BY p.likep DESC,p.pid ASC
LIMIT #{limit}
